// DEV SANITIZE: reclaim disk from build artifacts that are provably disposable, and nothing else.
//
//   node scripts/dev-sanitize.mjs            -> dry run: lists what WOULD go and how much space that is
//   node scripts/dev-sanitize.mjs --apply    -> deletes exactly that list
//
// Why it is safe by construction:
//  - It never walks the disk looking for names. Candidate locations come from an explicit ALLOWLIST of artifact classes, each one a
//    fixed path under <worktree>/src-tauri/target (cargo output, git-ignored, regenerated by `cargo build`), for the worktrees
//    `git worktree list` reports.
//  - The canonical DEV worktree (the one this script lives in) keeps its whole debug build: that is the executable the launcher
//    opens and the incremental cache that keeps rebuilds fast.
//  - `release/bundle` (installers) is always kept: it may be the only copy someone needs to reinstall.
//  - Human data (SmartLearn-DevData, database backups, sources) and source code are not on any allowlist, so they cannot be reached.
//  - A candidate is refused if it is a symlink/junction, resolves outside <worktree>/src-tauri/target, or holds a running process.
//  - Running it again after --apply finds nothing and changes nothing.
import { existsSync, lstatSync, readdirSync, realpathSync, rmSync, statfsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, dirname, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const defaultCanonicalRoot = resolve(here, '..');

/** The artifact classes. `path` is relative to <worktree>/src-tauri/target; `keep` are children that survive inside it. */
export const ARTIFACT_CLASSES = [
  { id: 'android-targets', path: 'aarch64-linux-android', appliesTo: 'all', why: 'Android cross-compile output; the Desktop DEV is Windows-only' },
  { id: 'android-targets', path: 'x86_64-linux-android', appliesTo: 'all', why: 'Android cross-compile output; the Desktop DEV is Windows-only' },
  { id: 'release-build-cache', path: 'release', appliesTo: 'all', keep: ['bundle'], why: 'release compile cache and the old release exe; installers under release/bundle are kept' },
  { id: 'non-canonical-debug', path: 'debug', appliesTo: 'non-canonical', why: 'debug build of a worktree that is not the canonical DEV one (the launcher refuses it)' },
  { id: 'non-canonical-cargo-metadata', path: '.rustc_info.json', appliesTo: 'non-canonical', why: 'cargo metadata file of a non-canonical worktree' },
];

export function listWorktreeRoots(cwd = defaultCanonicalRoot) {
  const text = execFileSync('git', ['worktree', 'list', '--porcelain'], { cwd, encoding: 'utf8' });
  return text.split(/\r?\n/).filter((l) => l.startsWith('worktree ')).map((l) => resolve(l.slice('worktree '.length)));
}

function sizeOf(path) {
  const st = lstatSync(path);
  if (!st.isDirectory()) return st.size;
  let total = 0;
  for (const name of readdirSync(path)) {
    try { total += sizeOf(join(path, name)); } catch { /* vanished or unreadable: counts as 0 */ }
  }
  return total;
}

const norm = (p) => resolve(p).toLowerCase();

/** Throws unless `path` is a real directory/file physically inside <root>/src-tauri/target. */
function assertInsideTarget(root, path) {
  const targetDir = join(root, 'src-tauri', 'target');
  const st = lstatSync(path);
  if (st.isSymbolicLink()) throw new Error(`refusing a symlink/junction: ${path}`);
  const real = realpathSync(path);
  const realTarget = realpathSync(targetDir);
  if (!(norm(real) + sep).startsWith(norm(realTarget) + sep) || norm(real) === norm(realTarget)) throw new Error(`refusing a path outside ${targetDir}: ${path}`);
}

function hasRunningProcess(path, runningPaths) {
  const prefix = norm(path) + sep;
  return runningPaths.some((p) => norm(p).startsWith(prefix));
}

/**
 * Builds the removal plan. Pure inspection: nothing is deleted here.
 * @param {{ roots: string[], canonicalRoot?: string, runningPaths?: string[] }} o roots = worktree roots (from `git worktree list`)
 */
export function planSanitize({ roots, canonicalRoot = defaultCanonicalRoot, runningPaths = [] }) {
  const canonical = norm(canonicalRoot);
  if (!roots.map(norm).includes(canonical)) throw new Error(`the canonical root ${canonicalRoot} is not one of the git worktrees`);
  const items = [];
  const skipped = [];
  for (const root of roots) {
    const isCanonical = norm(root) === canonical;
    const targetDir = join(root, 'src-tauri', 'target');
    if (!existsSync(targetDir)) continue;
    for (const cls of ARTIFACT_CLASSES) {
      if (cls.appliesTo === 'non-canonical' && isCanonical) continue;
      const base = join(targetDir, cls.path);
      if (!existsSync(base)) continue;
      const entries = cls.keep ? readdirSync(base).filter((n) => !cls.keep.includes(n)).map((n) => join(base, n)) : [base];
      for (const path of entries) {
        try {
          assertInsideTarget(root, path);
          if (hasRunningProcess(path, runningPaths)) { skipped.push({ path, reason: 'a running process lives here' }); continue; }
          items.push({ class: cls.id, path, bytes: sizeOf(path), why: cls.why, worktree: root });
        } catch (err) { skipped.push({ path, reason: err.message }); }
      }
    }
  }
  return { items, skipped, recoverableBytes: items.reduce((n, i) => n + i.bytes, 0) };
}

/** Deletes exactly the planned items (re-validating each one first). Returns the bytes actually reclaimed. */
export function applySanitize(plan, { roots }) {
  let reclaimed = 0;
  const removed = [];
  for (const item of plan.items) {
    if (!existsSync(item.path)) continue;
    assertInsideTarget(item.worktree, item.path);
    if (!roots.map(norm).includes(norm(item.worktree))) throw new Error(`worktree not in the allowlisted set: ${item.worktree}`);
    const bytes = sizeOf(item.path);
    rmSync(item.path, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
    reclaimed += bytes;
    removed.push(item.path);
  }
  return { reclaimedBytes: reclaimed, removed };
}

function runningSmartLearnPaths() {
  try {
    const out = execFileSync('powershell', ['-NoProfile', '-Command', "Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Path } | ForEach-Object { $_.Path }"], { encoding: 'utf8' });
    return out.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  } catch { return []; }
}

// Logical sizes can count hard-linked cargo files twice, so the free-space delta is the figure to trust.
const freeBytes = (path) => { const f = statfsSync(path); return Number(f.bavail) * Number(f.bsize); };
const gb = (bytes) => `${(bytes / 1024 ** 3).toFixed(2)} GB`;

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  const apply = process.argv.includes('--apply');
  const roots = listWorktreeRoots();
  const plan = planSanitize({ roots, runningPaths: runningSmartLearnPaths() });
  console.log(`DEV SANITIZE (${apply ? 'APPLY' : 'dry run'}) - canonical worktree: ${defaultCanonicalRoot}`);
  for (const i of plan.items) console.log(`  ${apply ? 'remove' : 'would remove'}  ${gb(i.bytes).padStart(9)}  [${i.class}]  ${i.path}`);
  for (const s of plan.skipped) console.log(`  SKIPPED  ${s.path}  (${s.reason})`);
  console.log(`Recoverable: ${gb(plan.recoverableBytes)}`);
  if (apply) {
    const freeBefore = freeBytes(defaultCanonicalRoot);
    const result = applySanitize(plan, { roots });
    console.log(`Reclaimed (sum of item sizes): ${gb(result.reclaimedBytes)} in ${result.removed.length} item(s)`);
    console.log(`Free space on the disk: ${gb(freeBefore)} -> ${gb(freeBytes(defaultCanonicalRoot))}`);
  } else {
    console.log('Nothing was deleted. Re-run with --apply to remove exactly the list above.');
  }
}
